package com.csust.eyediagnosis.workflow.persistence.repository;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.csust.eyediagnosis.workflow.persistence.entity.DiagnosisCitationEntity; import com.csust.eyediagnosis.workflow.persistence.mapper.DiagnosisCitationMapper; import org.springframework.stereotype.Repository; import java.util.Optional;
@Repository public class MybatisDiagnosisCitationRepository implements DiagnosisCitationRepository { private final DiagnosisCitationMapper mapper; public MybatisDiagnosisCitationRepository(DiagnosisCitationMapper mapper){this.mapper=mapper;} public int insert(DiagnosisCitationEntity e){return mapper.insert(e);} public Optional<DiagnosisCitationEntity> findByBusinessKey(String id,long epoch,String doc,String revision,String digest){return Optional.ofNullable(mapper.selectOne(new LambdaQueryWrapper<DiagnosisCitationEntity>().eq(DiagnosisCitationEntity::getWorkflowId,id).eq(DiagnosisCitationEntity::getRetrievalEpoch,epoch).eq(DiagnosisCitationEntity::getSourceDocumentId,doc).eq(DiagnosisCitationEntity::getSourceRevision,revision).eq(DiagnosisCitationEntity::getQuotedSpanDigest,digest)));} }
